    terms: [['Case study', 'Bài tập tình huống', '案例分析'], ['Problem solving', 'Giải quyết vấn đề', '问题解决'], ['Containment', 'Ngăn chặn', '围堵'], ['Effectiveness verification', 'Kiểm chứng hiệu quả', '有效性验证'], ['Horizontal deployment', 'Lan rộng (áp dụng ngang)', '横向展开']],
